preConditionHook:
// CONSECUTIVE UPSIDE BREAKOUTS (Brian's notes P8): the last eventCount
// breakout events were ALL upside: long; all downside: short. Kept distinct
// from BreakoutDirectionShare by Brian's decision, though under this reading
// it equals that rule at minShare 1.
// BREAKOUT EVENT SCAN (shared by BreakoutDirectionShare and
// ConsecutiveUpsideBreakouts, Brian's notes P4/P8). Walking back from bar 0,
// bar [i] is an UPSIDE breakout event when its high is above the prior
// breakoutBars-bar high (Extremes over bars i + 1 .. i + breakoutBars, seeded
// at i + 1, strict) and a DOWNSIDE event when its low is below the prior low;
// a bar doing both is ambiguous and skipped. The scan stops once eventCount
// events are seen, or after maxScanBars bars.
upN = 0;
dnN = 0;
seen = 0;
for (int ii = 0; ii <= (int)maxScanBars - 1; ++ii) {
    if (el_lt((double)seen, eventCount)) {
        hh = high[ii + 1];
        ll = low[ii + 1];
        for (int jj = 2; jj <= (int)breakoutBars; ++jj) {
            if (el_gt(high[ii + jj], hh)) hh = high[ii + jj];
            if (el_lt(low[ii + jj], ll)) ll = low[ii + jj];
        }
        isUp = el_gt(high[ii], hh);
        isDn = el_lt(low[ii], ll);
        if (isUp && !isDn) {
            upN = upN + 1;
            seen = seen + 1;
        } else if (isDn && !isUp) {
            dnN = dnN + 1;
            seen = seen + 1;
        }
    }
}
